        CheckResumeFileExtension: function (filename) {
            // debugger;
            var extension = filename.replace(/^.*\./, '');
            if (extension === filename) {
                extension = '';
            }
            else {
                extension = extension.toLowerCase();
            }
            //Check extension
            switch (extension) {
                case 'png':
                case 'jpeg':
                case 'jpg':
                case 'gif':
                case 'xlsx':
                case 'xls':
                case 'doc':
                case 'docx':
                case 'txt':
                case 'pdf':
                case 'csv':
                    return true;
                default:
                    return false;
            }
        },
